{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Raltitrexed, a structurally related antifolate with the same N10-methyl-benzoyl-glutamate motif, showed only 0.6–2% CSF penetration in nonhuman primates, indicating that this antifolate scaffold does not achieve meaningful CNS access after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A glutamate-diacid-containing radiotracer with an aromatic amide and two carboxylates exhibited negligible brain uptake (0.34 %ID/g) in mice, consistent with poor BBB penetration for highly polar, ionized glutamate conjugates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "5-Methyltetrahydrofolate, a natural reduced folate with a benzoyl-glutamate tail, equilibrated with CSF within 3 h in dogs, demonstrating that some folate vitamers can access CSF via active transport.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "5-Formyltetrahydrofolate was detected in mouse brain after IV administration, supporting transporter-mediated brain entry of natural folates.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Methotrexate is a highly polar, ionized antifolate with poor passive BBB permeability and known efflux liability. The closest antifolate analogue, raltitrexed, shows minimal CSF penetration, and glutamate-diacid radiotracers confirm poor brain uptake for this polar scaffold. Although natural folates can be actively transported into CSF, the oxidized 2,4-diaminopteridine antifolate structure of methotrexate does not share that efficient access, so meaningful CNS exposure after systemic administration is not supported.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for methotrexate itself is present in the provided evidence.",
    "Clinical high-dose methotrexate can achieve therapeutic CSF levels, which may qualify as meaningful access under some definitions, but this dose-dependent behavior is not captured by the analogue evidence.",
    "The extent to which methotrexate uses folate transporter pathways at the BBB/BCSFB relative to natural folates remains uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

